import { describe, it, assert, expect } from 'vitest';
import { TeltonikaCodec8eAVLPacket, TeltonikaDataCodec } from '../../src';

describe('TeltonikaCodec8eAVLPacket', () => {
  it('should throw an error if crc 16 is not matching', () => {
    assert.throws(
      () => {
        new TeltonikaCodec8eAVLPacket(
          Buffer.from('123456789123456789123456789')
        );
      },
      /CRC-16 validation failed/
    );
  });

  it('should parse IO correctly (wiki example 1)', () => {
    const raw = Buffer.from('000000000000004A8E010000016B412CEE000100000000000000000000000000000000010005000100010100010011001D00010010015E2C880002000B000000003544C87A000E000000001DD7E06A00000100002994', 'hex');
    const packet = new TeltonikaCodec8eAVLPacket(raw);
    const record = packet.records.at(0);

    expect(packet.state.preamble).toStrictEqual(Buffer.from([0x00, 0x00, 0x00, 0x00]));
    expect(packet.state.size).toBe(74);
    expect(packet.state.codecId).toBe(TeltonikaDataCodec.Codec8e);
    expect(packet.state.numberOfData1).toBe(1);
    expect(packet.state.numberOfData2).toBe(1);
    expect(packet.state.crc).toBe(packet.calculatedCrc);

    expect(record?.timestamp).toStrictEqual(new Date('2019-06-10T11:36:32.000Z'));
    expect(record?.priority).toBe(1);
    expect(record?.event).toBe(1);
    expect(record?.gps).toStrictEqual({
      longitude: 0,
      latitude: 0,
      altitude: 0,
      angle: 0,
      satellites: 0,
      speed: 0
    });

    expect(record?.io).toStrictEqual({
      1: Buffer.from([0x01]),
      11: Buffer.from([0x00, 0x00, 0x00, 0x00, 0x35, 0x44, 0xC8, 0x7A]),
      14: Buffer.from([0x00, 0x00, 0x00, 0x00, 0x1D, 0xD7, 0xE0, 0x6A]),
      16: Buffer.from([0x01, 0x5E, 0x2C, 0x88]),
      17: Buffer.from([0x00, 0x1D]),
    });
  });

  it('should parse big IO with NX of X Byte IO for crash event detection', () => {
    const raw = Buffer.from('', 'hex');
    const packet = new TeltonikaCodec8eAVLPacket(raw);
    const record = packet.records.at(0);
    
    expect(packet.state.preamble).toStrictEqual(Buffer.from([0x00, 0x00, 0x00, 0x00]));
    expect(packet.state.size).toBe(1361);
    expect(packet.state.codecId).toBe(TeltonikaDataCodec.Codec8e);
    expect(packet.state.numberOfData1).toBe(10);
    expect(packet.state.numberOfData2).toBe(10);
    expect(packet.state.crc).toBe(packet.calculatedCrc);

    expect(record?.timestamp).toStrictEqual(new Date('2026-04-03T07:07:49.000Z'));
    expect(record?.priority).toBe(0);
    expect(record?.event).toBe(247);
    expect(record?.gps).toStrictEqual({
      longitude: 0,
      latitude: 0,
      altitude: 0,
      angle: 0,
      satellites: 0,
      speed: 0
    });

    expect(record?.io).toStrictEqual({
      16: Buffer.from([0x00, 0x00, 0x00, 0x00]),
      17: Buffer.from([0x03, 0x43]),
      18: Buffer.from([0xf4, 0x46]),
      19: Buffer.from([0xfb, 0x5d]),
      21: Buffer.from([0x03]),
      67: Buffer.from([0x0e, 0xf0]),
      68: Buffer.from([0x00, 0x00]),
      69: Buffer.from([0x02]),
      70: Buffer.from([ 0x01, 0x55]),
      113: Buffer.from([0x50]),
      181: Buffer.from([ 0x03, 0xe8]),
      182: Buffer.from([0x03, 0xe8]),
      199: Buffer.from([ 0x00, 0x00, 0x00, 0x00]),
      200: Buffer.from([0x00]),
      239: Buffer.from([0x00]),
      240: Buffer.from([0x00]),
      247: Buffer.from([0x01]),
      800: Buffer.from([0x00, 0x00, 0x00, 0x00]),
      1429: Buffer.from([0x0a, 0xcb, 0xff, 0xbe, 0xf5, 0xc2, 0xfc, 0x98]),
      1430: Buffer.from([0x03]),
      1431: Buffer.from([0x00, 0x37]),
      1432: Buffer.from([0x0c, 0x92, 0x03, 0x33, 0xf4, 0x46, 0xfb, 0x5d]),
      13266: Buffer.from([0x05]),
      13267: Buffer.from([0x0a]),
    });

  });
});
